## Handling C Errors Safely

C functions communicate errors through return codes and global error state. Wrap them in safe XIOM functions that return `Result`.

### Return Code Pattern

```xiom
extern "C" {
  fn open_file(path: *const Char) -> Int;  // returns -1 on error
  fn close_file(fd: Int) -> Int;             // returns -1 on error
}

fn safe_open(path: Str) -> Result[Int, Str] {
  let fd = unsafe { open_file(path as *const Char) };
  if fd < 0 {
    return Err("Failed to open file");
  }
  return Ok(fd);
}

fn safe_close(fd: Int) -> Result[Unit, Str] {
  let result = unsafe { close_file(fd) };
  if result < 0 {
    return Err("Failed to close file");
  }
  return Ok(());
}
```

### Null Pointer Check

```xiom
extern "C" {
  fn get_user(id: Int) -> *const Unit;  // returns null on error
}

fn safe_get_user(id: Int) -> Result<*const Unit, Str> {
  let ptr = unsafe { get_user(id) };
  if ptr.is_null() {
    return Err("User not found");
  }
  return Ok(ptr);
}
```

### Wrapping Pattern

```xiom
// General pattern: unsafe C call → safe Result
fn wrap_c_call[T](c_result: Int, success_value: T, error_msg: Str) -> Result[T, Str] {
  if c_result == 0 {  // C: 0 = success
    return Ok(success_value);
  }
  return Err(error_msg);
}
```

### Cleanup on Error

```xiom
fn process_file(path: Str) -> Result[Int, Str] {
  let fd = safe_open(path)?;
  // ... use fd ...
  safe_close(fd)?;
  return Ok(0);
}
// If safe_open fails, ? propagates Err — no cleanup needed (nothing to close)
```

### Error Categories

```xiom
pub type FfiError = enum {
  NullPointer,
  ReturnCode(code: Int),
  InvalidUtf8,
}

fn to_result[T](ptr: *const T) -> Result[*const T, FfiError] {
  if ptr.is_null() { return Err(FfiError.NullPointer); }
  return Ok(ptr);
}
```

