extern "C" {
  fn do_work(input: Int) -> Int;
}

fn safe_do_work(input: Int) -> Result[Int, Str] {
  let result = unsafe { do_work(input) };
  if result < 0 {
    return Err("Operation failed");
  }
  return Ok(result);
}

fn main() -> Int {
  match safe_do_work(42) {
    Ok(_) => { return 0; }
    Err(_) => { return 1; }
  }
}
